"""Twenty original offline evaluation fixtures and behavioral reference outputs.

Reference solutions are oracle self-checks only; the live agent never receives
them. Public DOM IDs/function contracts are the test interface, not completion
markers or an implementation prescribed by the grader.
"""
import json


def ui(identity, title, body, brief, solution, oracle):
    html = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + title + '</title><link rel="stylesheet" href="styles.css"></head><body><main><h1>' + title + '</h1>' + body + '</main><script src="app.js"></script></body></html>'
    return dict(id=identity, category="app", prompt=brief + " Preserve the public element IDs as the integration contract. Implement in index.html/styles.css/app.js using plain browser code without dependencies or network calls. Keep a useful accessible interface.",
                files={"index.html": html, "styles.css": "body{font-family:system-ui;color:#172033;background:#ffffff}main{max-width:900px;margin:auto;padding:24px}button,input,select{font:inherit}button{cursor:pointer}\n", "app.js": "// Implement the requested user flow here.\n"},
                oracle=oracle, reference_files={"app.js": solution})


