    ui("cart-totals", "Basket", '<button data-add="mug">Add mug (£12.50)</button><button data-add="lamp">Add lamp (£40)</button><ul id="cart"></ul><p id="total">£0.00</p>',
       "Make the basket work. Adding a mug or lamp increases its quantity; each cart row exposes data-sku with its SKU, a labeled number input for quantity, and a remove button. Changing quantity updates totals exactly to two decimal places. Removing the final row returns an empty basket with £0.00.",
       "const prices={mug:1250,lamp:4000},cart={};function render(){const list=document.querySelector('#cart');list.replaceChildren();Object.entries(cart).forEach(([sku,qty])=>{const li=document.createElement('li');li.dataset.sku=sku;const label=document.createElement('label');label.textContent=sku+' quantity ';const input=document.createElement('input');input.type='number';input.min='1';input.value=qty;input.oninput=()=>{const value=Number(input.value);if(Number.isInteger(value)&&value>=1){cart[sku]=value;render()}};label.append(input);const remove=document.createElement('button');remove.textContent='Remove '+sku;remove.onclick=()=>{delete cart[sku];render()};li.append(label,remove);list.append(li)});document.querySelector('#total').textContent='£'+(Object.entries(cart).reduce((sum,[sku,qty])=>sum+prices[sku]*qty,0)/100).toFixed(2)}document.querySelectorAll('[data-add]').forEach(button=>button.onclick=()=>{cart[button.dataset.add]=(cart[button.dataset.add]||0)+1;render()});render();", "cart"),
