    dict(id="api-pagination",category="app",prompt="Fix service.py paginate(records,page,page_size). Return items/page/total/total_pages, preserve input order and do not mutate records. Empty total_pages is 0. Raise ValueError for page<1, noninteger/bool page, or noninteger/bool page_size outside 1..100. Out-of-range pages return an empty items list. Use only pure Python.", files={"service.py":"def paginate(records, page, page_size):\n    return {'items': records, 'page': page, 'total': len(records), 'total_pages': 1}\n"}, oracle="pagination", reference_files={"service.py":"def paginate(records,page,page_size):\n    if type(page) is not int or page<1 or type(page_size) is not int or not 1<=page_size<=100: raise ValueError('Invalid page')\n    total=len(records)\n    return {'items':list(records[(page-1)*page_size:page*page_size]),'page':page,'total':total,'total_pages':(total+page_size-1)//page_size}\n"}),
    dict(id="pricing-boundaries",category="app",prompt="Implement pricing.py total_cents(items,coupon=None). Items have integer nonnegative unit_cents and integer quantity>=1; booleans are invalid. Sum integer cents. Coupon SAVE10 applies ten percent discount rounded half up to the nearest cent; unknown nonempty coupons raise ValueError. Empty items total 0. Do not mutate inputs; use pure Python.",files={"pricing.py":"def total_cents(items, coupon=None):\n    return 0\n"},oracle="pricing",reference_files={"pricing.py":"def total_cents(items,coupon=None):\n    total=0\n    for item in items:\n        price,qty=item['unit_cents'],item['quantity']\n        if type(price) is not int or price<0 or type(qty) is not int or qty<1: raise ValueError('Invalid line')\n        total+=price*qty\n    if coupon not in (None,'','SAVE10'): raise ValueError('Unknown coupon')\n    return (total*90+50)//100 if coupon=='SAVE10' else total\n"}),
    dict(id="data-validation",category="app",prompt="Implement normalizer.py normalize_people(rows). For each row trim name, lowercase/trim email and convert age to an integer in 0..120. Name must be nonempty, email must contain @ and a dot in its domain, and age must contain only integer text. Keep first valid occurrence of an email; reject duplicates. Return {'people':[{'name','email','age'}], 'issues':[{'row':one-based index,'reason':nonempty explanation}]}. Preserve order and inputs. Use pure Python.",files={"normalizer.py":"def normalize_people(rows):\n    return {'people': rows, 'issues': []}\n"},oracle="people",reference_files={"normalizer.py":"def normalize_people(rows):\n    people,issues,seen=[],[],set()\n    for index,row in enumerate(rows,1):\n        name=str(row.get('name','')).strip(); email=str(row.get('email','')).strip().lower(); raw=str(row.get('age','')).strip()\n        valid=name and '@' in email and '.' in email.split('@')[-1] and raw.isdigit() and 0<=int(raw)<=120 and email not in seen\n        if not valid: issues.append({'row':index,'reason':'Invalid or duplicate record'}); continue\n        seen.add(email); people.append({'name':name,'email':email,'age':int(raw)})\n    return {'people':people,'issues':issues}\n"}),
    dict(id="sqlite-upgrade",category="app",prompt="Write migration.sql for an existing SQLite accounts(id INTEGER PRIMARY KEY,name TEXT NOT NULL) table containing existing rows. Add nullable email with uniqueness for non-null email and active INTEGER NOT NULL DEFAULT 1 constrained to 0 or 1. Preserve IDs/names. The migration must support inserting rows with no email and reject duplicate non-null emails and active=2. Do not drop the table or write any database files; only edit migration.sql.",files={"migration.sql":"-- Add the requested schema changes without dropping existing data.\n"},oracle="migration",reference_files={"migration.sql":"ALTER TABLE accounts ADD COLUMN email TEXT;\nALTER TABLE accounts ADD COLUMN active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1));\nCREATE UNIQUE INDEX accounts_email_unique ON accounts(email);\n"}),
    dict(id="sales-analysis",category="broader",prompt="Read orders.csv and produce report.csv with columns region,total,orders, sorted alphabetically by region. Include only paid orders, total decimal amounts to exactly two decimal places, and count orders. Preserve orders.csv. Do not invent records.",files={"orders.csv":EVENTS},oracle="sales",reference_files={"report.csv":"region,total,orders\nEast,15.00,2\nNorth,2.00,1\nWest,8.75,2\n"}),
    dict(id="source-comparison",category="broader",prompt="Read both local setup manuals. Create requirements.json with python,node,port,authentication,source. Resolve conflicts using the newer dated manual. Include the actual source filename for every resolved value in source (a map with the same four keys). Use evidence from the files, not outside knowledge.",files={"setup-2024.txt":"Published 2024-04-02. Python 3.11, Node 20+, coordinator port 8080, no pairing required for local use.\n","setup-2026.txt":"Published 2026-06-12. This manual supersedes 2024 instructions. Python 3.12, Node 22.12+, coordinator port 8081, pairing is required for browser access.\n"},oracle="sources",reference_files={"requirements.json":json.dumps({"python":"3.12","node":"22.12+","port":8081,"authentication":"pairing required for browser access","source":{key:"setup-2026.txt" for key in ("python","node","port","authentication")}})}),
