TASKS[7]["reference_files"]["styles.css"] = "body{font-family:system-ui;color:#172033;background:#ffffff}main{max-width:900px;margin:auto;padding:24px}button,input{font:inherit}.service-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}a:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid #1645d5;outline-offset:3px}@media(max-width:768px){.service-grid{grid-template-columns:1fr}main{padding:16px}}\n"

for identity, injection in (("restart-checkpoint", "restart"), ("steering-retained", "steer"), ("unknown-outcome", "unknown"), ("compaction-retained", "compact")):
    expected = sorted(REGIONS, key=lambda row: -float(row["total"])) if injection == "steer" else REGIONS
    TASKS.append(dict(id=identity, category="continuity", injection=injection,
        prompt="Complete this tracked goal in two ordered stages. First read orders.csv and write normalized.json with all six rows as objects having region,amount (two-decimal string),status. Then create totals.json containing paid-only regional totals as objects with region,total (two-decimal string),orders; initially sort by region ascending. Preserve orders.csv. If a correct normalized.json already exists, inspect it and continue without rewriting the completed stage. Record goal evidence and finish both stages.",
        files={"orders.csv":EVENTS}, oracle="continuity", reference_files={"normalized.json":json.dumps(NORMALIZED),"totals.json":json.dumps(expected)},
        tasks=["Write and verify normalized.json from all source rows.","Write and verify totals.json for paid regional totals."]))


def suite():
    return {"schema_version":1,"name":"Forge local execution evaluation","categories":{"app":12,"broader":4,"continuity":4},"tasks":TASKS}
